var NEW_ISSUE_URL = 'https://github.com/petercr/orca-entire-extension/issues/new'
var REPORT_ICON = ['M15 3h6v6', 'M10 14 21 3', 'M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6']

function platformName() {
  var platform = String(navigator.platform || '')
  return /^win/i.test(platform) ? 'Windows' : /^mac/i.test(platform) ? 'macOS' : 'Linux'
}

// A new issue from .github/ISSUE_TEMPLATE/bug_report.yml with its environment field filled in.
// It names versions and the kind of workspace only: no paths, repos or branches, which the
// person adds themselves if they want to.
function issueUrl(entry) {
  var lines = ['Entire for Orca: ' + PLUGIN_VERSION, 'Orca host API: ' + orca.api.major + '.' + orca.api.minor, 'OS: ' + platformName()]
  var version = entry && step(entry, 'version')
  if (version && version.ok) lines.push('Entire CLI: ' + version.text)
  if (entry) {
    var workspace = entry.workspace
    lines.push('Workspace: ' + (workspace.server ? 'on a paired Orca server' : /^WSL /.test(workspace.where || '') ? 'in WSL' : 'on this computer'))
  }
  return NEW_ISSUE_URL + '?template=bug_report.yml&environment=' + encodeURIComponent(lines.join('\n'))
}

// Orca opens a link only from a click in the panel, and asks the person before a new host.
function reportButton(entry) {
  var label = 'Report a problem on GitHub'
  var button = titled(el('button', 'report'), 'Opens a new GitHub issue for Entire for Orca')
  button.type = 'button'
  add(button, icon(REPORT_ICON), el('span', null, label))
  var timer = null
  function failed(text) {
    button.className = 'report bad'
    button.lastChild.textContent = text
    clearTimeout(timer)
    timer = setTimeout(function () {
      button.className = 'report'
      button.lastChild.textContent = label
    }, 3000)
  }
  button.addEventListener('click', function () {
    if (!orca.shell || !orca.host.has('shell.openExternal')) return failed("This Orca can't open links")
    orca.shell.openExternal(issueUrl(entry)).then(
      function (result) {
        if (result && result.opened === false && result.reason !== 'cancelled') failed("Couldn't open GitHub")
      },
      function () {
        failed("Couldn't open GitHub")
      }
    )
  })
  return button
}

function footer(entry) {
  return add(
    el('footer'),
    document.createTextNode('Checks Entire when you switch here, when an agent finishes and every 5 minutes. To check now, use ↻ or '),
    el('b', null, 'Entire: Refresh panel'),
    document.createTextNode('.'),
    el('br'),
    reportButton(entry)
  )
}

